import pandas as pd

def labels_need_cleaning(series):
    """Return True if the labels of the Series mix text with non-integer numbers."""
    try:
        return series.index.is_mixed_type()
    except AttributeError:
        # Fallback for older versions of pandas where is_mixed_type does not exist
        return any(isinstance(label, str) and not label.isdigit() for label in series.index)
```

