import numpy as np

def zero_of(spec):
    """Return the number zero as a NumPy scalar of the dtype given by spec (a string, a type or a dtype)."""
    return np.array(0, dtype=spec)
```

```python
import numpy as np

def zero_of(spec):
    """Return the number zero as a NumPy scalar of the dtype given by spec (a string, a type or a dtype)."""
    if isinstance(spec, str):
        return np.dtype(spec).type(0)
    elif isinstance(spec, type):
        return np.array([0], dtype=spec)[0]
    else:
        return np.array([0], dtype=spec.type)[0]
```

