```python
import pandas as pd

def closest_quarter(quarters, when):
    """Return the position of the period in the quarterly PeriodIndex closest to the given period."""
    # Use the `searchsorted` method to find the insertion point where `when` would go,
    # then adjust to get the nearest index.
    idx = quarters.searchsorted(when)
    if idx == len(quarters):
        return idx - 1
    elif idx == 0:
        return 0
    else:
        before = quarters[idx - 1]
        after = quarters[idx]
        if (when - before).days < (after - when).days:
            return idx - 1
        else:
            return idx
```

```python
import pandas as pd

def closest_quarter(quarters, when):
    """Return the position of the period in the quarterly PeriodIndex closest to the given period."""
    # Use the `searchsorted` method to find the insertion point for 'when' in the sorted index
    idx = quarters.searchsorted(when)
    if idx == len(quarters):
        return idx - 1
    elif idx == 0:
        return 0
    else:
        before = quarters[idx - 1]
        after = quarters[idx]
        if (when - before).days < (after - when).days:
            return idx - 1
        else:
            return idx
```

