import pandas as pd

def shipment_summary(shipments):
    """Return the summary statistics of the shipping dates and the weights, with the dates treated as
    numbers (count, mean, minimum, quartiles, maximum)."""
    # Convert datetime columns to numeric values before describing
    for col in shipments.select_dtypes(include=[pd.Timestamp]).columns:
        shipments[col] = shipments[col].astype('int64') // 10**9  # Convert to Unix timestamp
    return shipments.describe()
```

