```python
import pandas as pd

def parse_due_dates(invoices):
    """Return the due dates of the invoices as datetimes; clerks typed some as day/month/year and some as
    year-month-day."""
    # Use a custom function to handle both formats
    def parse_date(date_str):
        try:
            return pd.to_datetime(date_str, format='%d/%m/%Y')
        except ValueError:
            return pd.to_datetime(date_str, format='%Y-%m-%d')

    invoices['due'] = invoices['due'].apply(parse_date)
    return invoices['due']
```

