import numpy as np

def rows_within(table, low, high):
    """Return, for each row of the 2-D table, whether all of its values lie in [low, high]."""
    t = np.asarray(table)
    # Ensure that the comparison does not raise errors due to incompatible shapes or different dtypes
    if not np.can_cast(t.dtype, np.number):
        raise ValueError("Table must contain numeric data types")
    return np.all((t >= low) & (t <= high), axis=1)
```

