import numpy as np

def zero_of(spec):
    """Return the number zero as a NumPy scalar of the dtype given by spec (a string, a type or a dtype)."""
    if isinstance(spec, str):
        spec = np.dtype(spec)
    elif isinstance(spec, type):
        spec = np.dtype(spec)

    if spec.kind == 'c':  # Complex dtype
        return np.complex_(0)
    else:
        return np.zeros((), dtype=spec)

# Example usage:
print(zero_of('int32'))       # Output: 0
print(zero_of(np.float64))   # Output: 0.0
print(zero_of(complex))      # Output: 0j
```

